const input = $input.first().json;
const body = input.body || {};

const signatureObj = body.signature || {};
const timestamp = signatureObj.timestamp;
const token = signatureObj.token;
const signature = signatureObj.signature;

if (!timestamp || !token || !signature) {
  return [{
    json: {
      valid: false,
      response: {
        success: false,
        error: "UNAUTHORIZED",
        message: "Missing Mailgun signature parameters"
      },
      httpStatus: 401
    }
  }];
}

const nowSeconds = Math.floor(Date.now() / 1000);
const timestampNum = parseInt(timestamp, 10);
if (isNaN(timestampNum) || Math.abs(nowSeconds - timestampNum) > 900) {
  return [{
    json: {
      valid: false,
      response: {
        success: false,
        error: "UNAUTHORIZED",
        message: "Webhook timestamp expired or invalid"
      },
      httpStatus: 401
    }
  }];
}

const signingKey = (typeof $env !== 'undefined' && $env.MAILGUN_WEBHOOK_SIGNING_KEY) ||
                   (typeof process !== 'undefined' && process.env && process.env.MAILGUN_WEBHOOK_SIGNING_KEY) ||
                   '';

if (!signingKey || !signingKey.trim()) {
  return [{
    json: {
      valid: false,
      response: {
        success: false,
        error: "CONFIGURATION_ERROR",
        message: "Webhook signing key not configured"
      },
      httpStatus: 401
    }
  }];
}

function rightRotate(n, b) {
  return (n >>> b) | (n << (32 - b));
}

function sha256Bytes(bytes) {
  const K = [
    0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5,
    0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3, 0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174,
    0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc, 0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da,
    0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7, 0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967,
    0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13, 0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85,
    0xa2bfe8a1, 0xa81a664b, 0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070,
    0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3,
    0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208, 0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2
  ];

  const H = [
    0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a, 0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19
  ];

  const l = bytes.length;
  const bitLen = l * 8;
  const k = (448 - ((l + 1) % 64 * 8) + 512) % 512 / 8;
  const padded = new Uint8Array(l + 1 + k + 8);
  padded.set(bytes);
  padded[l] = 0x80;

  const view = new DataView(padded.buffer);
  view.setBigUint64(padded.length - 8, BigInt(bitLen), false);

  const w = new Int32Array(64);
  const pView = new DataView(padded.buffer);

  for (let offset = 0; offset < padded.length; offset += 64) {
    for (let i = 0; i < 16; i++) {
      w[i] = pView.getInt32(offset + i * 4, false);
    }
    for (let i = 16; i < 64; i++) {
      const s0 = (rightRotate(w[i - 15], 7) ^ rightRotate(w[i - 15], 18) ^ (w[i - 15] >>> 3));
      const s1 = (rightRotate(w[i - 2], 17) ^ rightRotate(w[i - 2], 19) ^ (w[i - 2] >>> 10));
      w[i] = (w[i - 16] + s0 + w[i - 7] + s1) | 0;
    }

    let a = H[0], b = H[1], c = H[2], d = H[3], e = H[4], f = H[5], g = H[6], h = H[7];

    for (let i = 0; i < 64; i++) {
      const S1 = rightRotate(e, 6) ^ rightRotate(e, 11) ^ rightRotate(e, 25);
      const ch = (e & f) ^ ((~e) & g);
      const temp1 = (h + S1 + ch + K[i] + w[i]) | 0;
      const S0 = rightRotate(a, 2) ^ rightRotate(a, 13) ^ rightRotate(a, 22);
      const maj = (a & b) ^ (a & c) ^ (b & c);
      const temp2 = (S0 + maj) | 0;

      h = g;
      g = f;
      f = e;
      e = (d + temp1) | 0;
      d = c;
      c = b;
      b = a;
      a = (temp1 + temp2) | 0;
    }

    H[0] = (H[0] + a) | 0;
    H[1] = (H[1] + b) | 0;
    H[2] = (H[2] + c) | 0;
    H[3] = (H[3] + d) | 0;
    H[4] = (H[4] + e) | 0;
    H[5] = (H[5] + f) | 0;
    H[6] = (H[6] + g) | 0;
    H[7] = (H[7] + h) | 0;
  }

  const result = new Uint8Array(32);
  const rView = new DataView(result.buffer);
  for (let i = 0; i < 8; i++) {
    rView.setInt32(i * 4, H[i], false);
  }
  return result;
}

function hmacSha256(keyStr, msgStr) {
  const enc = new TextEncoder();
  let keyBytes = enc.encode(keyStr);
  if (keyBytes.length > 64) {
    keyBytes = sha256Bytes(keyBytes);
  }
  const K = new Uint8Array(64);
  K.set(keyBytes);

  const o_key_pad = new Uint8Array(64);
  const i_key_pad = new Uint8Array(64);
  for (let i = 0; i < 64; i++) {
    o_key_pad[i] = K[i] ^ 0x5c;
    i_key_pad[i] = K[i] ^ 0x36;
  }

  const msgBytes = enc.encode(msgStr);
  const innerMsg = new Uint8Array(64 + msgBytes.length);
  innerMsg.set(i_key_pad, 0);
  innerMsg.set(msgBytes, 64);
  const innerHash = sha256Bytes(innerMsg);

  const outerMsg = new Uint8Array(64 + 32);
  outerMsg.set(o_key_pad, 0);
  outerMsg.set(innerHash, 64);
  const outerHash = sha256Bytes(outerMsg);

  return Array.from(outerHash).map(b => b.toString(16).padStart(2, '0')).join('');
}

const computedHmac = hmacSha256(signingKey, timestamp + token);

if (!computedHmac || computedHmac.toLowerCase() !== String(signature).toLowerCase()) {
  return [{
    json: {
      valid: false,
      response: {
        success: false,
        error: "UNAUTHORIZED",
        message: "Invalid Mailgun webhook signature"
      },
      httpStatus: 401
    }
  }];
}

const eventData = body['event-data'] || body.eventData;
if (!eventData) {
  return [{
    json: {
      valid: false,
      response: {
        success: false,
        error: "VALIDATION_ERROR",
        message: "Missing 'event-data' in webhook payload"
      },
      httpStatus: 400
    }
  }];
}

const rawEvent = eventData.event || 'unknown';
const rawSeverity = eventData.severity || null;

let eventType = rawEvent;
let status = rawEvent.toUpperCase();

if (rawEvent === 'failed') {
  if (rawSeverity === 'permanent') {
    eventType = 'bounced';
    status = 'BOUNCED';
  } else {
    eventType = 'failed';
    status = 'FAILED_TEMPORARY';
  }
} else if (rawEvent === 'delivered') {
  status = 'DELIVERED';
} else if (rawEvent === 'complained') {
  status = 'SPAM_COMPLAINT';
} else if (rawEvent === 'rejected') {
  status = 'REJECTED';
}

const recipient = eventData.recipient || (eventData.message && eventData.message.recipients ? eventData.message.recipients[0] : null);

const messageHeaders = (eventData.message && eventData.message.headers) || {};
const messageId = messageHeaders['message-id'] || messageHeaders['Message-Id'] || null;

const deliveryStatus = eventData['delivery-status'] || {};
const details = {
  reason: eventData.reason || deliveryStatus.message || deliveryStatus.description || null,
  severity: rawSeverity,
  code: deliveryStatus.code || null,
  description: deliveryStatus.description || null
};

const userVariables = eventData['user-variables'] || {};
const metadata = {
  tenantId: userVariables.tenantId || null,
  registrationId: userVariables.registrationId || null,
  correlationId: userVariables.correlationId || null,
  template: userVariables.template || null
};

const eventId = eventData.id || `evt_${Date.now()}`;
const eventTimestamp = eventData.timestamp ? new Date(eventData.timestamp * 1000).toISOString() : new Date().toISOString();

const isAlertable = ['BOUNCED', 'FAILED_TEMPORARY', 'SPAM_COMPLAINT', 'REJECTED'].includes(status) || ['bounced', 'failed', 'complained', 'rejected'].includes(eventType);

const alertText = `ACYA Email Service detected an email delivery problem.

Event:
${status || eventType}

Recipient:
${recipient || 'N/A'}

Template:
${metadata.template || 'N/A'}

Tenant:
${metadata.tenantId || 'N/A'}

Registration:
${metadata.registrationId || 'N/A'}

Correlation ID:
${metadata.correlationId || 'N/A'}

Mailgun Message ID:
${messageId || 'N/A'}

Mailgun Event ID:
${eventId || 'N/A'}

Timestamp:
${eventTimestamp}

Reason:
${details.reason || 'N/A'}

Severity:
${details.severity || 'N/A'}

This is an operational notification only.`;

return [{
  json: {
    valid: true,
    eventId: eventId,
    eventType: eventType,
    status: status,
    recipient: recipient,
    messageId: messageId,
    timestamp: eventTimestamp,
    details: details,
    metadata: metadata,
    isAlertable: isAlertable,
    alertSubject: `[ACYA Email Alert] Email ${eventType || status}`,
    alertText: alertText,
    response: {
      success: true,
      processed: true,
      eventId: eventId,
      eventType: eventType
    }
  }
}];
